// Hand-built simulator for verifying a planned move list (not a search).
const DIRS = {U:[0,-1], D:[0,1], L:[-1,0], R:[1,0]};
let g = {}; // "x,y" -> token: S crystal, W, C, G, D, '.' empty
const init = {
 "2,2":"C","3,2":"S","4,2":"S","5,2":"S","6,2":"D",
 "2,3":"S","3,3":"S","4,3":"S","5,3":"S","6,3":"S",
 "2,4":"S","3,4":"S","4,4":"S","5,4":"S","6,4":"W",
 "2,5":"G","3,5":"S","4,5":"S","5,5":"S",
 "2,6":"S","3,6":"S","4,6":"S","5,6":"S"};
let gatesOpen = false;
let lost = null;
function inInterior(x,y){ return x>=2 && x<=6 && y>=2 && y<=6; }
function isGateCell(x,y){ return (x===6 && (y===5||y===6)); }
function passable(x,y){ // for beams/walking: non-wall, not closed gate
  if(!inInterior(x,y)) return false;
  if(isGateCell(x,y)) return gatesOpen;
  return true;
}
function get(x,y){ if(isGateCell(x,y)&&!gatesOpen) return '|'; return g[x+','+y]||'.'; }
function set(x,y,t){ g[x+','+y]=t; }
function findW(){ for(const k in g) if(g[k]==='W') return k.split(',').map(Number); }
function find(t){ for(const k in g) if(g[k]===t) return k.split(',').map(Number); return null; }
function adj(a,b){ return Math.abs(a[0]-b[0])+Math.abs(a[1]-b[1])===1; }
function wMove(d){
  const [dx,dy]=DIRS[d]; const [wx,wy]=findW();
  let k=1;
  while(true){
    const x=wx+k*dx, y=wy+k*dy;
    if(!passable(x,y)) return 'refused';
    const t=get(x,y);
    if(t==='S'||t==='C'||t==='G'||t==='D'){
      set(wx,wy,t); set(x,y,'W'); return 'swap with '+t+' at '+x+','+y;
    }
    k++;
  }
}
